import six
import logging
import socket
import traceback
from .exception import ExecuteTimeout


class TCPExecutor(object):
    def __init__(self, host, port, encoding='utf-8', socket_timeout=30, default_retry_timeout=30):
        self._host = host
        self._port = port
        self._socket_timeout = float(socket_timeout)
        self._default_retry_timeout = float(default_retry_timeout)
        self._buffer_size = 1024
        self._encoding = encoding

    def connect(self):
        conn = socket.socket(socket.AF_INET, socket.SOCK_STREAM)
        conn.settimeout(self._socket_timeout)
        try:
            log_msg = "Trying to connect to host={}, port={}"
            log_msg = log_msg.format(self._host, self._port)
            logging.info(log_msg)
            conn.connect((self._host, self._port))
            self._conn = conn
            return conn
        except socket.error as e:
            logging.error(str(e))
            raise

    def execute_until(self, msg, timeout=None):
        timeout = timeout or self._default_retry_timeout
        # start = time.time()
        # while time.time() - start < timeout:
        try:
            return self.execute(msg, timeout=timeout)
        except:  # noqa E722
            raise ExecuteTimeout('Socket connection timed out. {}'.format(traceback.format_exc()))

    def execute(self, msg, timeout=None):
        timeout = timeout or self._socket_timeout
        self._conn.settimeout(timeout)
        self.send(msg=msg)
        return self.receive()

    def receive(self):
        try:
            response = self._conn.recv(self._buffer_size)
            if six.PY3:
                return str(response, encoding=self._encoding)
            return response
        except socket.timeout as e:
            logging.error(str(e))
            raise

    def send(self, msg):
        if six.PY3 and isinstance(msg, str):
            encoded_msg = msg.encode(self._encoding)
        else:
            encoded_msg = msg
        self._conn.send(encoded_msg)

    def disconnect(self):
        self._conn.shutdown(socket.SHUT_WR)
        self._conn.close()
